def choose_move(observation):
    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def clamp_move(dx, dy):
        return [0 if dx < -1 else 1 if dx > 1 else dx, 0 if dy < -1 else 1 if dy > 1 else dy]

    def md(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def first_pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return [x[0], x[1]]
        return None

    env = observation.get("environment_name", "resource_collection")
    self_pos = first_pos(observation.get("self_position")) or [0, 0]
    opp_pos = first_pos(observation.get("opponent_position")) or self_pos
    sx, sy = self_pos[0], self_pos[1]
    ox, oy = opp_pos[0], opp_pos[1]

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return clamp_move(sign(ox - sx), sign(oy - sy))
        gw = observation.get("grid_width", 0)
        gh = observation.get("grid_height", 0)
        corners = [[0, 0], [0, gh - 1], [gw - 1, 0], [gw - 1, gh - 1]]
        target = max(corners, key=lambda c: md(c, opp_pos))
        return clamp_move(sign(target[0] - sx), sign(target[1] - sy))

    if env == "territory_control":
        cells = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        best = None
        best_score = None
        for item in cells:
            p = first_pos(item)
            if p is None:
                continue
            score = md(self_pos, p) - md(opp_pos, p)
            if best is None or score < best_score or (score == best_score and md(self_pos, p) < md(self_pos, best)):
                best = p
                best_score = score
        if best is None:
            return [0, 0]
        return clamp_move(sign(best[0] - sx), sign(best[1] - sy))

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_score = None
    for item in resources:
        p = first_pos(item)
        if p is None:
            continue
        score = md(self_pos, p) + max(0, 3 - md(opp_pos, p))
        if best is None or score < best_score:
            best = p
            best_score = score

    if best is None:
        return clamp_move(sign(ox - sx), sign(oy - sy))

    return clamp_move(sign(best[0] - sx), sign(best[1] - sy))

